import{_ as e,o as s,c as t,ag as l}from"./chunks/framework.i8sMDeRW.js";const u=JSON.parse('{"title":"第 1 课：什么是 LLM？","description":"","frontmatter":{},"headers":[],"relativePath":"guide/12-llm-engineering/01-llm-basics.md","filePath":"guide/12-llm-engineering/01-llm-basics.md","lastUpdated":1779765503000}'),p={name:"guide/12-llm-engineering/01-llm-basics.md"};function n(i,a,o,d,c,r){return s(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="第-1-课-什么是-llm" tabindex="-1">第 1 课：什么是 LLM？ <a class="header-anchor" href="#第-1-课-什么是-llm" aria-label="Permalink to &quot;第 1 课：什么是 LLM？&quot;">​</a></h1><blockquote><p>本课目标：用最简单的语言理解大语言模型是什么、它怎么生成回答、它和数据库有什么不同，以及产品经理为什么需要理解它。</p></blockquote><hr><h2 id="_1-简单定义" tabindex="-1">1. 简单定义 <a class="header-anchor" href="#_1-简单定义" aria-label="Permalink to &quot;1. 简单定义&quot;">​</a></h2><p>LLM 是 <strong>Large Language Model</strong>，中文叫<strong>大语言模型</strong>。</p><p>简单说：</p><blockquote><p>LLM 是一个读过大量文字的 AI，它学会了语言里的规律，然后根据你的问题生成回答。</p></blockquote><p>它不是像人一样真正“理解世界”，更像一个非常强的自动补全系统。</p><p>例如你输入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>中国的首都是</span></span></code></pre></div><p>模型很可能继续生成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京</span></span></code></pre></div><p>你输入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写一封请假邮件</span></span></code></pre></div><p>模型会根据以前见过的大量邮件格式，生成一封看起来合理的邮件。</p><hr><h2 id="_2-生活类比" tabindex="-1">2. 生活类比 <a class="header-anchor" href="#_2-生活类比" aria-label="Permalink to &quot;2. 生活类比&quot;">​</a></h2><p>想象一个人读过很多书、网页、代码、邮件、客服对话和产品文档。</p><p>读得多了以后，他看到一句话的开头，就能猜后面应该怎么接。</p><p>LLM 做的事情，本质上也是：</p><blockquote><p>根据前面的内容，预测后面最可能出现的文字。</p></blockquote><hr><h2 id="_3-它不是数据库" tabindex="-1">3. 它不是数据库 <a class="header-anchor" href="#_3-它不是数据库" aria-label="Permalink to &quot;3. 它不是数据库&quot;">​</a></h2><p>很多初学者会以为：</p><blockquote><p>LLM 里面存着一张巨大的“问题-答案表”。</p></blockquote><p>其实不是。</p><p>它更像是学会了很多语言和知识的规律。</p><p>比如它不一定存着某一句完整的退款政策，但它见过很多退款政策，所以知道退款政策一般会包含：</p><ul><li>退款时间</li><li>退款条件</li><li>不可退款情况</li><li>联系方式</li><li>处理流程</li></ul><p>所以你让它写退款政策，它能生成一份。</p><hr><h2 id="_4-大-是什么意思" tabindex="-1">4. “大”是什么意思？ <a class="header-anchor" href="#_4-大-是什么意思" aria-label="Permalink to &quot;4. “大”是什么意思？&quot;">​</a></h2><p>“大语言模型”里的“大”，通常是指模型有很多<strong>参数</strong>。</p><p>参数可以理解成：</p><blockquote><p>模型内部很多很多可以调整的小旋钮。</p></blockquote><p>训练模型时，这些小旋钮会不断被调整，让模型越来越会预测文字。</p><p>一个模型可能有：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>7B 参数 = 70 亿个参数</span></span></code></pre></div><p>也可能有：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>70B 参数 = 700 亿个参数</span></span></code></pre></div><p>但注意：</p><blockquote><p>模型越大，不一定越适合你。</p></blockquote><p>大模型通常更强，但也更贵、更慢、更难部署。</p><p>小模型如果数据好、任务明确，也可以非常实用。</p><hr><h2 id="_5-llm-怎么回答问题" tabindex="-1">5. LLM 怎么回答问题？ <a class="header-anchor" href="#_5-llm-怎么回答问题" aria-label="Permalink to &quot;5. LLM 怎么回答问题？&quot;">​</a></h2><p>非常简化的流程是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的文字</span></span>
<span class="line"><span>→ 切成 token</span></span>
<span class="line"><span>→ token 变成数字</span></span>
<span class="line"><span>→ 模型处理这些数字</span></span>
<span class="line"><span>→ 预测下一个 token</span></span>
<span class="line"><span>→ 不断重复</span></span>
<span class="line"><span>→ 生成完整回答</span></span></code></pre></div><p>也就是说：</p><blockquote><p>模型不是直接“看懂中文”，而是把文字变成数字，再做数学计算。</p></blockquote><p>后面我们会详细讲：</p><ul><li>token 是什么</li><li>tokenization 是什么</li><li>embedding 是什么</li><li>transformer 是什么</li><li>attention 是什么</li></ul><hr><h2 id="_6-它能做什么" tabindex="-1">6. 它能做什么？ <a class="header-anchor" href="#_6-它能做什么" aria-label="Permalink to &quot;6. 它能做什么？&quot;">​</a></h2><p>LLM 可以用来：</p><ul><li>回答问题</li><li>写文章</li><li>写代码</li><li>总结文档</li><li>翻译</li><li>做客服</li><li>做 AI Copilot</li><li>做自动化工作流</li></ul><p>但它不是万能的。</p><p>它容易在这些场景出问题：</p><ul><li>事实要求很高的问题</li><li>需要最新信息的问题</li><li>企业内部私有知识</li><li>多步骤严谨推理</li><li>需要调用真实系统的任务</li></ul><p>所以 AI 产品设计不是简单地“接一个模型 API”。</p><p>真正的 AI 产品通常还需要：</p><ul><li>数据</li><li>检索</li><li>工具</li><li>权限</li><li>评估</li><li>监控</li><li>成本控制</li><li>人工兜底</li></ul><hr><h2 id="_7-对产品经理有什么用" tabindex="-1">7. 对产品经理有什么用？ <a class="header-anchor" href="#_7-对产品经理有什么用" aria-label="Permalink to &quot;7. 对产品经理有什么用？&quot;">​</a></h2><p>产品经理不需要一开始就会训练模型，但需要理解模型能力边界。</p><p>你需要知道：</p><table tabindex="0"><thead><tr><th>问题</th><th>为什么重要</th></tr></thead><tbody><tr><td>模型适合做这个任务吗？</td><td>避免为了 AI 而 AI</td></tr><tr><td>需要 RAG 还是微调？</td><td>影响方案复杂度和成本</td></tr><tr><td>输出是否可以被验证？</td><td>影响上线风险</td></tr><tr><td>用户能不能接受错误？</td><td>影响交互和兜底设计</td></tr><tr><td>成本是否可控？</td><td>影响商业模式</td></tr></tbody></table><p>如果你不知道 LLM 的基本工作方式，就很容易把 AI 产品设计成“看起来很酷，但上线后不稳定”的功能。</p><hr><h2 id="_8-本课总结" tabindex="-1">8. 本课总结 <a class="header-anchor" href="#_8-本课总结" aria-label="Permalink to &quot;8. 本课总结&quot;">​</a></h2><p>LLM 是一个通过大量文字训练出来的 AI 模型。</p><p>它的核心能力是：</p><blockquote><p>根据上下文，预测接下来最可能出现的文字。</p></blockquote><p>它不是普通数据库，也不是人类大脑。</p><p>它是一个强大的语言模式生成器。</p><hr><h2 id="_9-心智模型" tabindex="-1">9. 心智模型 <a class="header-anchor" href="#_9-心智模型" aria-label="Permalink to &quot;9. 心智模型&quot;">​</a></h2><p>把 LLM 想成：</p><blockquote><p>一个非常博学、非常会接话的助手。</p></blockquote><p>你给它：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务 + 背景 + 要求</span></span></code></pre></div><p>它就根据学过的模式生成回答。</p><p>输入越清楚，输出通常越好。</p><hr><h2 id="_10-初学者常见错误" tabindex="-1">10. 初学者常见错误 <a class="header-anchor" href="#_10-初学者常见错误" aria-label="Permalink to &quot;10. 初学者常见错误&quot;">​</a></h2><h3 id="错误-1-以为-ai-永远是对的" tabindex="-1">错误 1：以为 AI 永远是对的 <a class="header-anchor" href="#错误-1-以为-ai-永远是对的" aria-label="Permalink to &quot;错误 1：以为 AI 永远是对的&quot;">​</a></h3><p>LLM 会犯错，而且有时会很自信地犯错。</p><p>这叫<strong>幻觉</strong>，也就是 AI 编了一个看起来很真的答案。</p><h3 id="错误-2-以为模型越大越好" tabindex="-1">错误 2：以为模型越大越好 <a class="header-anchor" href="#错误-2-以为模型越大越好" aria-label="Permalink to &quot;错误 2：以为模型越大越好&quot;">​</a></h3><p>不一定。</p><p>实际项目里要考虑：</p><ul><li>成本</li><li>速度</li><li>准确率</li><li>部署难度</li><li>是否能本地运行</li><li>是否适合你的业务场景</li></ul><h3 id="错误-3-把提示词和微调混为一谈" tabindex="-1">错误 3：把提示词和微调混为一谈 <a class="header-anchor" href="#错误-3-把提示词和微调混为一谈" aria-label="Permalink to &quot;错误 3：把提示词和微调混为一谈&quot;">​</a></h3><p><strong>提示词 Prompting</strong>：通过更好的指令，让模型回答得更好。</p><p><strong>微调 Fine-tuning</strong>：用新的训练数据，改变模型的行为习惯。</p><h3 id="错误-4-以为模型天然懂你的业务" tabindex="-1">错误 4：以为模型天然懂你的业务 <a class="header-anchor" href="#错误-4-以为模型天然懂你的业务" aria-label="Permalink to &quot;错误 4：以为模型天然懂你的业务&quot;">​</a></h3><p>模型不一定知道你的公司、产品、客户和内部文档。</p><p>要让它懂你的业务，通常需要：</p><ul><li>把资料放进 prompt</li><li>做 RAG</li><li>做微调</li><li>接工具</li><li>建记忆系统</li></ul><hr><h2 id="_11-小练习" tabindex="-1">11. 小练习 <a class="header-anchor" href="#_11-小练习" aria-label="Permalink to &quot;11. 小练习&quot;">​</a></h2><p>问任意一个 AI：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用“餐厅”的比喻解释什么是大语言模型。</span></span></code></pre></div><p>然后再问：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用“老师”的比喻解释什么是大语言模型。</span></span></code></pre></div><p>比较两个回答的不同。</p><p>你会发现：</p><blockquote><p>同一个概念，可以通过不同 prompt 得到不同风格的解释。</p></blockquote><hr><h2 id="_12-小项目" tabindex="-1">12. 小项目 <a class="header-anchor" href="#_12-小项目" aria-label="Permalink to &quot;12. 小项目&quot;">​</a></h2><p>创建一个“LLM 概念解释器 prompt”：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一个耐心的老师。</span></span>
<span class="line"><span>解释 [主题]，要求：</span></span>
<span class="line"><span>1. 一个简单定义</span></span>
<span class="line"><span>2. 一个生活类比</span></span>
<span class="line"><span>3. 一个例子</span></span>
<span class="line"><span>4. 一个初学者误区</span></span>
<span class="line"><span>5. 一个小练习</span></span>
<span class="line"><span></span></span>
<span class="line"><span>主题：大语言模型</span></span></code></pre></div><p>然后把主题换成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>token</span></span>
<span class="line"><span>embedding</span></span>
<span class="line"><span>fine-tuning</span></span>
<span class="line"><span>RAG</span></span>
<span class="line"><span>agent</span></span></code></pre></div><p>练习目标：</p><blockquote><p>学会用稳定结构，让模型稳定输出你想要的解释。</p></blockquote><hr><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p><a href="./02-token-tokenization-context.html">第 2 课：Token、Tokenization 和上下文窗口</a></p>`,119)])])}const b=e(p,[["render",n]]);export{u as __pageData,b as default};
